INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-011', 'SW', 'P1', 'OPEN', NULL, NULL, 'MULTI-SLUG FILING BREAKS citation_mining_completeness''s PER-SLUG SEMANTICS, AND GAP-009''s FIX IS WHAT OPENED IT. citation_mining is keyed per (slug, local_ref_id) and log_mining writes one row per (slug, ref_id), but the outstanding-work query joins cm.global_ref_id = es.ref_id with NO slug predicate, and evidence_sources.citation_mining_status is a single flag per source rather than per link. While every source had exactly one slug those two were equivalent and nothing could tell them apart. They are no longer equivalent: a source linked to five slugs now has its R2 obligation discharged for all five by one mining pass logged under one of them. The legacy fallback cuts the other way -- cm2 joins on (cm2.slug = ssl.slug AND cm2.local_ref_id = ssl.local_ref_id), so a source with five links fans out and the four non-matching rows report NULL, reproducing the false-UNMINED shape that join was added to prevent. NEITHER DIRECTION IS DETECTED TODAY. Found by an adversarial code review of batch 15, not by a check. The honest statement of cause: this is a consequence of adding db.py link-source-slug, so the cross-slug capability and this defect arrived together and the second must be closed before the GAP-009 backlog is worked at scale -- backfilling batches 01-14 would multiply it across the whole corpus. Derive the exposure rather than quoting it: count sources with more than one slug link, and compare citation_mining rows per (slug, ref_id) against source_slug_links rows per (slug, ref_id).', '2026-09-18 04:59', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', '2026-09-18 04:59', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-012', 'SW', 'P1', 'OPEN', NULL, NULL, 'EVERY retrieval_log.fetch() CALL IN BATCHES 10-15 OMITS ref_id=, SO THE VERBATIM CHECK RESOLVES TO ITS WEAK BRANCH. quote_in_artefacts(quote, ref_id=...) compares rec.get(''ref_id'') == ref_id to choose between a SCOPED hit and an UNSCOPED one, and the UNSCOPED detail says in its own words that the match proves the words are in the corpus, not that they came from this source. With ref_id null on every artefact, a claim_text belonging to one source verifies identically against another source''s persisted payload -- so the control that exists to stop the 2026-08-19 fabrication is running in its weakened mode across six batches. Batches 08 and 09 populated ref_id; 10 through 15 do not, which makes this a REGRESSION rather than a gap that was never closed. CONSEQUENCE FOR THE RECORD: batch 15''s attestation states that every claim_text verifies byte-for-byte against a persisted artefact, and that is true only in the unscoped sense -- the words are provably in the session''s own retrieval log, but the binding between a quote and the source it is attributed to was not mechanically proved. Found by an adversarial code review, not by a check, and no check asserts that a manifest record carries a ref_id. FIX: pass ref_id= on every fetch that retrieves for a known source, and add an assertion that a batch''s manifest records are ref_id-scoped wherever the source was known at retrieval time.', '2026-09-18 04:59', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', '2026-09-18 04:59', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', NULL, NULL, NULL, NULL, NULL);